// Alerta para o contato de `contato_alerta`. No máximo um por motivo a cada
// `alerta_intervalo_seg`; os demais só entram na contagem do próximo.
function montarAlerta(cfg, motivo, texto) {
  if (!String(cfg.contato_alerta || '').trim()) return null;
  const st = $getWorkflowStaticData('global');
  const chaveAt = 'alertaAt_' + motivo, chaveOcultos = 'alertaOcultos_' + motivo;
  if (Date.now() - Number(st[chaveAt] || 0) < Number(cfg.alerta_intervalo_seg ?? 60) * 1000) {
    st[chaveOcultos] = Number(st[chaveOcultos] || 0) + 1;
    return null;
  }
  const ocultos = Number(st[chaveOcultos] || 0);
  st[chaveAt] = Date.now();
  st[chaveOcultos] = 0;
  return ocultos ? `${texto}\n(+${ocultos} parecido(s) nos últimos minutos)` : texto;
}

const cfgMsg = (cfg, k) => String(cfg[k] ?? '').replace(/\\n/g, '\n');
const juntar = (...partes) => partes.map(p => String(p ?? '').trim()).filter(Boolean).join('\n\n');

const body = $('Webhook Vocero').first().json.body || {};
const m = body.message || {};
const s = $('Carregar sessão').first().json;
const cfg = s.config || {};
let ctx = s.contexto || {};
let estado = s.estado || 'INICIO';
let tentativas = s.tentativas || 0;
const msgs = [];
let chamar = 'nenhuma';
let transbordo = false;
let nota = null;
let alerta = null;
let textoFallback = '';

// Resposta fora do esperado: no limite, passa para o atendente e o bot se cala.
// Sem isso, ele conversa sem parar com qualquer resposta automática.
const invalida = (...textos) => {
  ctx.invalidas = Number(ctx.invalidas || 0) + 1;
  if (ctx.invalidas >= Number(cfg.max_respostas_invalidas || 3)) {
    ctx.invalidas = 0;
    msgs.push(cfgMsg(cfg, 'msg_transbordo'));
    transbordo = true;
    nota = 'Bot MDF-e: limite de respostas inválidas; o bot parou de responder nesta conversa.';
    alerta = montarAlerta(cfg, 'invalidas', `⚠️ Bot MDF-e: limite de respostas inválidas\nContato: ${tel}`);
    estado = 'SILENCIO';
  } else if (cfg.ia_ativa === 'true' && m.type === 'text' && String(m.text || '').trim()) {
    chamar = 'ia';
    textoFallback = juntar(...textos);
  } else msgs.push(...textos);
};

// Telefone do remetente — a API aceita qualquer formato; mandamos 55+DDD+9+número
let tel = String(body.contact?.phone || '').replace(/\D/g, '');
if (tel.length === 12 && tel.startsWith('55')) tel = tel.slice(0, 4) + '9' + tel.slice(4);

const timeoutMin = Number(cfg.timeout_sessao_min || 60);
const idadeMin = (Date.now() - new Date(s.updated_at).getTime()) / 60000;
if (s.nova !== true && idadeMin > timeoutMin) estado = 'INICIO';
if (estado === 'FIM') estado = 'INICIO';

const texto = String(m.text || '').trim().toLowerCase();
const opcao = texto.replace(/^0+(?=\d)/, '');
const midia = m.media || null;
const mime = String(midia?.mimeType || '').toLowerCase();
// Mídia ainda em recuperação (available: false) entra na janela: é baixada depois.
const isArquivo = ['image', 'document'].includes(m.type) && !!midia && (midia.available === false ||
  /^(image\/(jpeg|png|webp|tiff)|application\/pdf)$/.test(mime));

// A fila do Vocero reentrega o que falhou. Texto mais antigo que o último recebido
// não vale mais: responder agora traria de volta um assunto que já passou.
const ocorreu = Date.parse(body.occurredAt || '');
const ultimoEvento = Date.parse(s.ultimo_evento_em || '');
if (!isArquivo && ocorreu < ultimoEvento) return [];

if (estado !== 'INICIO' && ['menu', '0'].includes(texto)) estado = 'VOLTAR_MENU';

// Texto junto com o documento: quem está na janela confere e responde.
const janelaSeg = Number(cfg.janela_arquivos_seg || 20) + 10;
const idadeArquivoSeg = (Date.now() - new Date(s.ultimo_arquivo_em || 0).getTime()) / 1000;
if (!isArquivo && estado === 'AGUARDANDO_DAMDFE' && (ctx.arquivos || []).length && idadeArquivoSeg < janelaSeg) return [];

if (isArquivo && estado !== 'VALIDANDO') {
  // Foto ou PDF vale em qualquer momento, sem passar pelo menu.
  chamar = 'aguardar_arquivos';
} else if (estado === 'INICIO') {
  ctx = {}; tentativas = 0;
  msgs.push(cfgMsg(cfg, 'msg_saudacao'), cfgMsg(cfg, 'msg_menu'));
  estado = 'MENU';
} else if (estado === 'VOLTAR_MENU') {
  ctx = {}; tentativas = 0;
  msgs.push(cfgMsg(cfg, 'msg_menu'));
  estado = 'MENU';
} else if (estado === 'MENU' || (estado === 'HUMANO' && ['1', '2'].includes(opcao))) {
  if (opcao === '1') {
    ctx = { arquivos: [] }; tentativas = 0;
    msgs.push(cfgMsg(cfg, 'msg_pedir_damdfe'));
    estado = 'AGUARDANDO_DAMDFE';
  } else if (opcao === '2') {
    if (cfg.cargas_ativo === 'true') {
      msgs.push(cfgMsg(cfg, 'msg_pedir_localizacao'));
      estado = 'CARGAS_AGUARDANDO_LOCAL';
    } else msgs.push(cfgMsg(cfg, 'msg_cargas_em_breve'));
  } else {
    invalida(cfgMsg(cfg, 'msg_opcao_invalida'), cfgMsg(cfg, 'msg_menu'));
  }
} else if (estado === 'HUMANO') {
  // Caso entregue à operação: não reabre o menu sozinho, só oferece a volta.
  invalida(cfgMsg(cfg, 'msg_voltar_menu'));
} else if (estado === 'AGUARDANDO_DAMDFE') {
  invalida(cfgMsg(cfg, 'msg_pedir_arquivo'));
} else if (estado === 'VALIDANDO') {
  msgs.push(cfgMsg(cfg, 'msg_aguarde'));
} else if (estado === 'CARGAS_AGUARDANDO_LOCAL') {
  // Fluxo 2 ainda não definido: guarda a localização e passa para o atendente
  ctx.localizacao = m.type === 'location' && m.location ? m.location : { texto: m.text || '' };
  msgs.push(cfgMsg(cfg, 'msg_cargas_recebido'), cfgMsg(cfg, 'msg_voltar_menu'));
  transbordo = true;
  nota = 'Bot MDF-e: motorista pediu cargas na região. Localização: ' + JSON.stringify(ctx.localizacao);
  estado = 'HUMANO';
}

return [{ json: {
  sessaoId: s.id,
  conversationId: body.conversationId,
  messageId: m.id,
  telefone: tel,
  estado, contexto: ctx, tentativas,
  texto: juntar(...msgs),
  transbordo, nota, chamar, alerta, notaRetorno: null, textoFallback, textoRecebido: String(m.text || '').slice(0, 500),
  registro: null,
  config: cfg,
} }];

const cfg = $('Decidir').first().json.config;
const baseUrl = String(cfg.api_mdfe_base_url || '').replace(/\/+$/, '');
const st = $getWorkflowStaticData('global');
const req = opts => this.helpers.httpRequest({ returnFullResponse: true, ignoreHttpStatusErrors: true,
  json: false, timeout: 30000, ...opts });
const parse = b => { if (b == null) return null; if (typeof b === 'string') { try { return JSON.parse(b); } catch { return { raw: b.slice(0, 500) }; } } return b; };
const agora = () => Date.now();
const guardar = (j, comRefresh) => {
  st.mdfeAccess = j.access_token; st.mdfeAccessExp = agora() + 29 * 60 * 1000;
  if (comRefresh && j.refresh_token) { st.mdfeRefresh = j.refresh_token; st.mdfeRefreshExp = agora() + 7 * 24 * 3600 * 1000 - 3600 * 1000; }
};
async function login() {
  const user = $env.MDFE_API_USER, pass = $env.MDFE_API_PASS;
  if (!user || !pass) throw new Error('sem_credencial');
  const r = await req({ method: 'POST', url: baseUrl + '/auth/login',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'username=' + encodeURIComponent(user) + '&password=' + encodeURIComponent(pass) });
  if (r.statusCode !== 200) {
    const erro = new Error(r.statusCode === 401 ? 'login_401' : 'login_http_' + r.statusCode);
    erro.detalhe = parse(r.body)?.detail ?? null;
    throw erro;
  }
  guardar(parse(r.body), true);
}
async function refresh() {
  if (!st.mdfeRefresh || (st.mdfeRefreshExp || 0) < agora()) return false;
  const r = await req({ method: 'POST', url: baseUrl + '/auth/refresh',
    headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ refresh_token: st.mdfeRefresh }) });
  if (r.statusCode !== 200) return false;
  guardar(parse(r.body), false);
  return true;
}
async function garantirToken() {
  if (st.mdfeAccess && (st.mdfeAccessExp || 0) > agora() + 60000) return;
  if (await refresh()) return;
  await login();
}

const d = $('Decidir').first().json;
const ids = $('Listar arquivos').all().map(i => i.json.messageId);
const baixados = $input.all();
const IMG = /^image\/(jpeg|png|webp|tiff)$/;
const ext = { 'application/pdf': '.pdf', 'image/jpeg': '.jpg', 'image/png': '.png', 'image/webp': '.webp', 'image/tiff': '.tif' };
const midias = [];
for (let i = 0; i < baixados.length; i++) {
  const bin = baixados[i].binary?.data;
  if (!bin) continue;
  const mime = String(bin.mimeType || '').split(';')[0].trim().toLowerCase();
  if (mime !== 'application/pdf' && !IMG.test(mime)) continue;
  const fileName = String(bin.fileName && /\.\w+$/.test(bin.fileName) ? bin.fileName : 'damdfe_' + ids[i] + ext[mime]).replace(/["\r\n]/g, '');
  midias.push({ id: ids[i], mime, bin: { ...bin, mimeType: mime, fileName } });
}
// Regra da API: 1 PDF ou de 1 a 3 imagens, sem misturar
const pdf = midias.find(m => m.mime === 'application/pdf');
const sel = pdf ? [pdf] : midias.slice(0, 3);
const out = { arquivosIds: sel.map(m => m.id), http: null, resposta: null, falha: null, baseUrl, telefone: d.telefone, qtd: sel.length };
if (sel.length === 0) { out.falha = 'sem_midia'; return [{ json: out }]; }
try {
  await garantirToken();
} catch (e) {
  out.falha = String((e && e.message) || e).slice(0, 200);
  out.falhaDetalhe = e?.detalhe ?? null;
  return [{ json: out }];
}
// Os bytes não passam por aqui: o nó Code só repassa as referências dos arquivos.
const binary = {};
sel.forEach((m, i) => { binary['f' + i] = m.bin; });
return [{ json: { ...out, token: st.mdfeAccess }, binary }];

const cfg = $('Decidir').first().json.config;
const baseUrl = String(cfg.api_mdfe_base_url || '').replace(/\/+$/, '');
const st = $getWorkflowStaticData('global');
const req = opts => this.helpers.httpRequest({ returnFullResponse: true, ignoreHttpStatusErrors: true,
  json: false, timeout: 30000, ...opts });
const parse = b => { if (b == null) return null; if (typeof b === 'string') { try { return JSON.parse(b); } catch { return { raw: b.slice(0, 500) }; } } return b; };
const agora = () => Date.now();
const guardar = (j, comRefresh) => {
  st.mdfeAccess = j.access_token; st.mdfeAccessExp = agora() + 29 * 60 * 1000;
