const cfgMsg = (cfg, k) => String(cfg[k] ?? '').replace(/\\n/g, '\n');
const d = $('IA: preparar').first().json;
const cfg = d.config;
const r = $input.first().json;
const INTENCOES = ['encerrar_mdfe', 'ver_cargas', 'como_enviar', 'ver_menu', 'fora_do_escopo'];

// Só o que está na lista vale: qualquer outro retorno da IA é descartado.
let intencao = null;
const conteudo = r.choices?.[0]?.message?.content;
try { intencao = JSON.parse(String(conteudo)).intencao; } catch {
  intencao = INTENCOES.find(i => String(conteudo || '').includes(i)) || null;
}
if (!INTENCOES.includes(intencao)) intencao = null;

const out = { ...d, chamar: 'nenhuma', iaBody: undefined };
const ctx = { ...(d.contexto || {}) };
if (intencao === 'encerrar_mdfe') {
  ctx.arquivos = ctx.arquivos || [];
  out.estado = 'AGUARDANDO_DAMDFE';
  out.texto = cfgMsg(cfg, 'msg_pedir_damdfe');
} else if (intencao === 'ver_cargas') {
  if (cfg.cargas_ativo === 'true') {
    out.estado = 'CARGAS_AGUARDANDO_LOCAL';
    out.texto = cfgMsg(cfg, 'msg_pedir_localizacao');
  } else out.texto = cfgMsg(cfg, 'msg_cargas_em_breve');
} else if (intencao === 'como_enviar') {
  out.texto = cfgMsg(cfg, 'msg_ia_como_enviar');
} else if (intencao === 'ver_menu') {
  out.estado = 'MENU';
  out.texto = cfgMsg(cfg, 'msg_menu');
} else if (intencao === 'fora_do_escopo') {
  out.texto = cfgMsg(cfg, 'msg_ia_fora_escopo');
} else {
  // IA fora do ar ou resposta inválida: segue com a mensagem fixa.
  out.texto = d.textoFallback;
  const erro = r.error?.message || r.error || (conteudo ? 'resposta fora da lista' : 'sem resposta');
  out.alerta = montarAlerta(cfg, 'ia', `⚠️ IA do bot MDF-e não respondeu\nMotivo: ${String(erro).slice(0, 200)}`);
}
out.contexto = ctx;
return [{ json: out }];

// E-mail de diagnóstico. Roda depois dos outros ramos para saber também se as
// entregas falharam (alerta sem chave válida, por exemplo). Sem destinatário, não faz nada.
const d = $('Saída').first().json;
const cfg = d.config;
const para = String(cfg.email_alerta_para || '').trim();
if (!para) return [];

const reg = d.registro;
const falhaEntrega = (no, rotulo) => {
  try {
    if (!$(no).isExecuted) return null;
    const erro = $(no).first().json?.error;
    return erro ? `${rotulo}: ${String(erro.message || erro).slice(0, 300)}` : null;
  } catch { return null; }
};
const entregas = [
  falhaEntrega('Avisar conferindo', 'Aviso de conferindo ao motorista'),
  falhaEntrega('Vocero: enviar mensagem', 'Resposta ao motorista'),
  falhaEntrega('Vocero: enviar alerta', 'Alerta no WhatsApp'),
  falhaEntrega('Vocero: anotar retorno', 'Observações do contato'),
].filter(Boolean);
const docFalhou = reg && !['encerrado', 'validado'].includes(reg.status);
if (!docFalhou && !d.alerta && !entregas.length) return [];

const cod = String(reg?.codigo || '');
const motivo = cod || (entregas.length ? 'entrega' : 'aviso');
const st = $getWorkflowStaticData('global');
const intervalo = Number(cfg.email_intervalo_seg ?? 60) * 1000;
if (Date.now() - Number(st['emailAt_' + motivo] || 0) < intervalo) {
  st['emailOcultos_' + motivo] = Number(st['emailOcultos_' + motivo] || 0) + 1;
  return [];
}
const ocultos = Number(st['emailOcultos_' + motivo] || 0);
st['emailAt_' + motivo] = Date.now();
st['emailOcultos_' + motivo] = 0;

const ETAPAS = ['Baixar o arquivo do Vocero', 'Login na API de MDF-e', 'Enviar o documento à API', 'Conferência na API'];
let parou = -1;
if (docFalhou) {
  if (cod === 'SEM_MIDIA') parou = 0;
  else if (/^(login_|sem_credencial)/.test(cod)) parou = 1;
  else if (/^(rede|ARQUIVO_GRANDE)/.test(cod)) parou = 2;
  else parou = 3;
}

const FAZER = {
  HTTP_500: 'A falha aconteceu dentro da API de MDF-e, que não informou a causa. Procure este horário nos logs da API. O erro 500 não diz se o MDF-e foi encerrado: confira a situação dele antes de reenviar.',
  HTTP_422: 'A API não conseguiu ler o arquivo. Teste com outro PDF ou foto.',
  HTTP_429: 'A API limitou as chamadas. Espere alguns minutos e tente de novo.',
  HTTP_503: 'A API está indisponível. Verifique o serviço e tente de novo.',
  SEM_MIDIA: 'O n8n não conseguiu baixar o arquivo do Vocero. Confira a credencial x-internal-key do nó Baixar mídia e se a mídia existe na conversa.',
  ARQUIVO_GRANDE: 'O arquivo passou do limite de 15 MB. Peça um PDF ou uma foto menor.',
  login_401: 'A API recusou o login. Confira MDFE_API_USER e MDFE_API_PASS no container do n8n.',
  sem_credencial: 'Faltam MDFE_API_USER e MDFE_API_PASS no container do n8n.',
  RESPOSTA_INESPERADA: 'A resposta da API não segue o contrato combinado. Compare o retorno abaixo com a documentação da API.',
  TELEFONE_NAO_E_DO_MOTORISTA: 'Confira se o telefone abaixo é o do motorista cadastrado neste MDF-e.',
};
let fazer = FAZER[cod];
if (!fazer && /^login_/.test(cod)) fazer = 'O login na API falhou. Verifique o serviço da API.';
if (!fazer && /^rede/.test(cod)) fazer = 'O n8n não alcançou a API. Verifique a URL api_mdfe_base_url e o serviço da API.';
if (!fazer && /^HTTP_/.test(cod)) fazer = 'A API devolveu um status inesperado. Veja o retorno abaixo e os logs da API.';
if (!fazer && reg?.status) fazer = 'A API recusou o documento. Veja o código e a mensagem abaixo.';
if (!fazer) fazer = 'Veja os detalhes abaixo e a execução no n8n.';

const base = String(cfg.n8n_url || '').replace(/\/+$/, '');
const linhas = [];
if (d.alerta && !reg) linhas.push(d.alerta, '');
if (reg) {
  linhas.push('ONDE PAROU', '✓ Documento recebido no Vocero');
  ETAPAS.forEach((e, i) => {
    if (!docFalhou || i < parou) linhas.push('✓ ' + e);
    else if (i === parou) linhas.push(`✗ ${e} — ${cod || '-'}${reg.http_status ? ' (HTTP ' + reg.http_status + ')' : ''}`);
    else linhas.push('– ' + e + ' (não chegou aqui)');
  });
  linhas.push('');
}
if (entregas.length) linhas.push('ENTREGAS QUE FALHARAM', ...entregas.map(e => '✗ ' + e), 'Confira as credenciais desses nós: docs/n8n/bot-motorista-mdfe/CREDENCIAIS.md', '');
if (docFalhou) linhas.push('O QUE FAZER', fazer, '');
linhas.push('DADOS',
  'Quando: ' + new Date().toLocaleString('pt-BR', { timeZone: 'America/Cuiaba' }),
  'Telefone: ' + (d.telefone || '-'),
  'Conversa: ' + (d.conversationId || '-'));
if (reg) linhas.push(
  'Status: ' + (reg.status || '-'),
  'Código: ' + (cod || '-'),
  'Protocolo: ' + (reg.protocolo || '-'),
  'Chave: ' + (reg.chave_mdfe || '-'),
  'Mensagem: ' + (reg.mensagem || '-'));
linhas.push('Execução no n8n: ' + (base ? `${base}/workflow/${$workflow.id}/executions/${$execution.id}` : String($execution.id)));
if (ocultos) linhas.push(`Parecidos omitidos desde o último e-mail: ${ocultos}`);
linhas.push('', 'O QUE O MOTORISTA RECEBEU', d.texto || '(nada)');
if (reg) linhas.push('', 'RETORNO DA API', reg.retorno_api ? JSON.stringify(reg.retorno_api, null, 2).slice(0, 6000) : '(sem retorno)');

const titulo = reg && docFalhou ? `${cod || 'erro'} em ${ETAPAS[parou]}` : (entregas.length ? 'entrega falhou' : 'aviso');
return [{ json: {
  para,
  de: String(cfg.email_remetente || para),
  assunto: `[Bot MDF-e] ${titulo} — ${d.telefone || '-'}`,
  texto: linhas.join('\n'),
} }];
